def wiredecode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")

    n = len(data)
    i = 0
    result = []

    def read_varint(start):
        idx = start
        res = 0
        shift = 0
        count = 0

        while idx < n:
            b = data[idx]
            idx += 1
            count += 1

            if count > 10:
                raise ValueError("varint too long")

            res |= (b & 0x7F) << shift
            shift += 7

            if not (b & 0x80):
                if count >= 2 and b == 0x00:
                    raise ValueError("non-minimal encoding")
                if res >= (1 << 64):
                    raise ValueError("value too large")
                return res, idx

            if count == 10:
                raise ValueError("varint too long")

        raise ValueError("unexpected end of data in varint")

    while i < n:
        tag, i = read_varint(i)

        wire = tag & 7
        field = tag >> 3

        if field < 1 or field > (1 << 29) - 1:
            raise ValueError("Invalid field number")
        if 19000 <= field <= 19999:
            raise ValueError("Reserved field number")

        if wire == 0:
            val, i = read_varint(i)
            result.append((field, wire, val))
        elif wire == 1:
            if i + 8 > n:
                raise ValueError("Truncated 64-bit value")
            val = int.from_bytes(data[i:i+8], byteorder='little', signed=False)
            i += 8
            result.append((field, wire, val))
        elif wire == 5:
            if i + 4 > n:
                raise ValueError("Truncated 32-bit value")
            val = int.from_bytes(data[i:i+4], byteorder='little', signed=False)
            i += 4
            result.append((field, wire, val))
        elif wire == 2:
            length, i = read_varint(i)
            if i + length > n:
                raise ValueError("Truncated length-delimited value")
            val = bytes(data[i:i+length])
            i += length
            result.append((field, wire, val))
        else:
            raise ValueError(f"Unsupported wire type {wire}")

    return result

def crcrocksoft(data, width, poly, init, refin, refout, xorout):
    # Type and Value Checks
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")

    # width must be int, not bool, and in range [1, 64]
    if type(width) is not int or isinstance(width, bool):
        raise ValueError("width must be an int")
    if not (1 <= width <= 64):
        raise ValueError("width must be between 1 and 64")

    # poly, init, xorout must be int, not bool, and in range [0, 2**width)
    for val, name in [(poly, "poly"), (init, "init"), (xorout, "xorout")]:
        if type(val) is not int or isinstance(val, bool):
            raise ValueError(f"{name} must be an int")
        if not (0 <= val < (1 << width)):
            raise ValueError(f"{name} must be < 2**{width}")

    # refin, refout must be bool
    if type(refin) is not bool:
        raise ValueError("refin must be True or False")
    if type(refout) is not bool:
        raise ValueError("refout must be True or False")

    mask = (1 << width) - 1
    reg = init

    for byte in data:
        # Determine bit order for this byte
        if refin:
            # LSB first: bits 0 to 7
            bits = [(byte >> i) & 1 for i in range(8)]
        else:
            # MSB first: bits 7 to 0
            bits = [(byte >> i) & 1 for i in range(7, -1, -1)]

        for b in bits:
            t = (reg >> (width - 1)) & 1
            reg = (reg << 1) & mask
            if (t ^ b) & 1:
                reg ^= poly

    if refout:
        # Reverse bits of reg within width bits
        reversed_reg = 0
        for i in range(width):
            if (reg >> i) & 1:
                reversed_reg |= (1 << (width - 1 - i))
        reg = reversed_reg

    reg ^= xorout
    return reg

def v6canon(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    # Check ASCII
    if not text.isascii():
        raise ValueError("Non-ASCII characters not allowed")

    # Check for whitespace
    if any(c.isspace() for c in text):
        raise ValueError("Whitespace not allowed")

    # Check forbidden chars
    if any(c in text for c in ['%', '/', '[', ']']):
        raise ValueError("Forbidden characters found")

    if not text:
        raise ValueError("Empty string")

    # Locate ::
    double_colon_index = text.find('::')

    # Helper functions
    def parse_hex(s):
        if not s:
            raise ValueError("Empty group")
        if len(s) > 4:
            raise ValueError("Group too long")
        # Check chars are valid hex
        for c in s:
            if c not in '0123456789abcdefABCDEF':
                raise ValueError("Invalid hex character")
        try:
            val = int(s, 16)
        except ValueError:
            raise ValueError("Invalid hex")
        if val > 0xFFFF:
            raise ValueError("Group value out of range")
        return val

    def parse_ipv4(s):
        parts = s.split('.')
        if len(parts) != 4:
            raise ValueError("IPv4 format error")
        octets = []
        for p in parts:
            if not p:
                raise ValueError("IPv4 empty octet")
            if len(p) > 3:
                raise ValueError("IPv4 octet too long")
            # Check digits
            if not all(c in '0123456789' for c in p):
                raise ValueError("IPv4 non-digit")
            val = int(p)
            if val > 255:
                raise ValueError("IPv4 octet out of range")
            # No leading zeros
            if len(p) > 1 and p[0] == '0':
                raise ValueError("IPv4 leading zero")
            octets.append(val)
        # Combine to 2 hex groups
        g1 = (octets[0] << 8) | octets[1]
        g2 = (octets[2] << 8) | octets[3]
        return [g1, g2]

    if double_colon_index == -1:
        # No ::
        groups_strs = text.split(':')
        if len(groups_strs) != 8:
            raise ValueError("Invalid number of groups")
        if any(g == '' for g in groups_strs):
            raise ValueError("Invalid group separator")

        result_groups = []
        for i, g in enumerate(groups_strs):
            is_last = (i == 7)
            if '.' in g:
                if not is_last:
                    raise ValueError("IPv4 suffix not at end")
                vals = parse_ipv4(g)
                result_groups.extend(vals)
            else:
                result_groups.append(parse_hex(g))

        if len(result_groups) != 8:
            raise ValueError("Group count mismatch")

    else:
        # With ::
        # Check for :::
        if ':::' in text:
            raise ValueError("Triple colon")
        # Check multiple ::
        if text.count('::') > 1:
            raise ValueError("Multiple ::")

        before = text[:double_colon_index]
        after = text[double_colon_index + 2:]

        left_groups = []
        if before:
            left_groups = before.split(':')
            if any(g == '' for g in left_groups):
                raise ValueError("Invalid group separator")

        right_groups = []
        if after:
            right_groups = after.split(':')
            if any(g == '' for g in right_groups):
                raise ValueError("Invalid group separator")

        num_explicit = len(left_groups) + len(right_groups)
        num_zeros = 8 - num_explicit

        if num_zeros < 1:
            raise ValueError("Too many groups")

        result_groups = []
        for g in left_groups:
            result_groups.append(parse_hex(g))

        for _ in range(num_zeros):
            result_groups.append(0)

        # Process right groups
        # The last group of the address is the last element of right_groups (if any)
        # If right_groups is empty, the address ends with ::, so last group is 0 (already added)

        # Determine if the last group (index 7) comes from right_groups
        # If right_groups is not empty, its last element corresponds to index 7.
        # If right_groups is empty, index 7 is a zero group.

        if right_groups:
            last_right_idx = len(right_groups) - 1
            for i, g in enumerate(right_groups):
                is_last = (i == last_right_idx)
                if '.' in g:
                    if not is_last:
                        raise ValueError("IPv4 suffix not at end")
                    vals = parse_ipv4(g)
                    result_groups.extend(vals)
                else:
                    result_groups.append(parse_hex(g))
        else:
            # right_groups empty, result_groups already has 8 zeros if num_zeros=8?
            # Wait, if right_groups empty, num_zeros = 8 - len(left).
            # We added num_zeros zeros.
            # Total length should be 8.
            pass

        if len(result_groups) != 8:
            raise ValueError("Group count mismatch")

    # Canonicalization
    # Format hex strings
    hex_groups = [f"{g:x}" for g in result_groups]

    # Find longest run of zeros
    # We need to find the start and length of the longest run of "0" strings
    # But wait, we are working with integer groups.
    # A run of zeros means groups with value 0.

    max_run_len = 0
    max_run_start = -1

    current_run_len = 0
    current_run_start = -1

    for i, g in enumerate(result_groups):
        if g == 0:
            if current_run_len == 0:
                current_run_start = i
            current_run_len += 1
        else:
            if current_run_len > max_run_len:
                max_run_len = current_run_len
                max_run_start = current_run_start
            current_run_len = 0
            current_run_start = -1

    # Check last run
    if current_run_len > max_run_len:
        max_run_len = current_run_len
        max_run_start = current_run_start

    # RFC 5952: replace longest run of 2 or more zero groups
    if max_run_len >= 2:
        # Replace groups from max_run_start to max_run_start + max_run_len with ::
        # But we need to handle the string construction carefully.
        # We can build the string parts.

        # Left part: groups before the run
        left_part = ':'.join(hex_groups[:max_run_start])
        # Right part: groups after the run
        right_part = ':'.join(hex_groups[max_run_start + max_run_len:])

        if left_part and right_part:
            return f"{left_part}::{right_part}"
        elif left_part:
            return f"{left_part}::"
        elif right_part:
            return f"::{right_part}"
        else:
            return "::"
    else:
        return ':'.join(hex_groups)

