def udp4_inspect(packet):
    if not isinstance(packet, (bytes, bytearray)):
        raise ValueError("packet must be bytes or bytearray")

    if len(packet) < 20:
        raise ValueError("Packet too short for IPv4 header")

    ver_ihl = packet[0]
    if (ver_ihl >> 4) != 4:
        raise ValueError("Not an IPv4 packet")

    ihl = ver_ihl & 0x0F
    hdr_len = ihl * 4
    if hdr_len < 20 or hdr_len > len(packet):
        raise ValueError("Invalid IHL or header length out of bounds")

    tot_len = (packet[2] << 8) | packet[3]
    if tot_len < hdr_len or tot_len > len(packet):
        raise ValueError("Invalid total length")

    # IPv4 header checksum
    hdr = packet[:hdr_len]
    cs = 0
    for i in range(0, len(hdr), 2):
        cs += (hdr[i] << 8) | hdr[i+1]
    while cs > 0xFFFF:
        cs = (cs & 0xFFFF) + (cs >> 16)
    if cs != 0xFFFF:
        raise ValueError("Invalid IPv4 header checksum")

    flags_frag = (packet[6] << 8) | packet[7]
    if flags_frag & 0x8000:
        raise ValueError("Reserved bit must be 0")
    if flags_frag & 0x2000:
        raise ValueError("More fragments bit must be 0")
    if flags_frag & 0x1FFF:
        raise ValueError("Fragment offset must be 0")

    if packet[9] != 17:
        raise ValueError("Protocol must be UDP (17)")

    seg = packet[hdr_len:tot_len]
    if len(seg) < 8:
        raise ValueError("UDP segment too short")

    udp_len = (seg[4] << 8) | seg[5]
    if udp_len < 8 or udp_len > len(seg):
        raise ValueError("Invalid UDP length")

    datagram = seg[:udp_len]
    udp_chk = (datagram[6] << 8) | datagram[7]
    checksummed = False

    if udp_chk != 0:
        checksummed = True
        pseudo = packet[12:16] + packet[16:20] + b'\x00' + b'\x11' + seg[4:6]
        chk_data = pseudo + datagram
        if len(chk_data) & 1:
            chk_data += b'\x00'

        cs = 0
        for i in range(0, len(chk_data), 2):
            cs += (chk_data[i] << 8) | chk_data[i+1]
        while cs > 0xFFFF:
            cs = (cs & 0xFFFF) + (cs >> 16)
        if cs != 0xFFFF:
            raise ValueError("Invalid UDP checksum")

    return {
        "src": '.'.join(str(b) for b in packet[12:16]),
        "dst": '.'.join(str(b) for b in packet[16:20]),
        "ttl": packet[8],
        "sport": (seg[0] << 8) | seg[1],
        "dport": (seg[2] << 8) | seg[3],
        "payload": bytes(datagram[8:]),
        "checksummed": checksummed
    }

def urlnorm3986(url: str) -> str:
    # Character sets
    UNRESERVED = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~')
    SUB_DELIMS = set("!$&'()*+,;=")
    SCHEME_CHARS = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-.')
    USERINFO_CHARS = UNRESERVED | SUB_DELIMS | set(':')
    HOST_REGNAME_CHARS = UNRESERVED | SUB_DELIMS
    PATH_CHARS = UNRESERVED | SUB_DELIMS | set(':@/')
    QUERY_FRAGMENT_CHARS = UNRESERVED | SUB_DELIMS | set(':@/?')
    IP_LITERAL_CHARS = set('0123456789abcdefABCDEF:.')

    # Input validation
    for c in url:
        if not (0x21 <= ord(c) <= 0x7E):
            raise ValueError("Input contains non-printable ASCII or space")

    def validate_and_normalize_percent(s: str, allowed: set) -> str:
        res = []
        i = 0
        while i < len(s):
            c = s[i]
            if c == '%':
                if i + 2 >= len(s):
                    raise ValueError("Invalid percent encoding")
                hex_part = s[i+1:i+3]
