def achilles_up_to(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an int")
    if n < 1 or n > 10**15:
        raise ValueError("n must be between 1 and 10**15 inclusive")

    if n == 1:
        return 0

    # 1. Count powerful numbers up to n
    # Every powerful number m <= n can be uniquely written as m = a^2 * b^3 with b square-free.
    # We iterate over square-free b such that b^3 <= n.
    limit_b = int(n**(1/3)) + 2
    is_sq_free = bytearray([1]) * (limit_b + 1)
    for i in range(2, int(limit_b**0.5) + 1):
        if is_sq_free[i]:
            for j in range(i*i, limit_b + 1, i*i):
                is_sq_free[j] = 0

    powerful_count = 0
    for b in range(1, limit_b + 1):
        if is_sq_free[b]:
            b3 = b * b * b
            if b3 > n:
                break
            powerful_count += math.isqrt(n // b3)

    # 2. Count perfect powers up to n (excluding 1)
    # Formula: sum_{e=2}^{floor(log2 n)} -mu(e) * (floor(n^(1/e)) - 1)
    max_e = n.bit_length()
    pp_count = 0
    for e in range(2, max_e + 1):
        # Compute mu(e) and check if e is square-free
        temp = e
        mu = 1
        is_sq_free_e = True
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                temp //= d
                if temp % d == 0:
                    is_sq_free_e = False
                    break
                mu = -mu
            d += 1
        if temp > 1:
            mu = -mu

        if not is_sq_free_e:
            continue

        # Compute floor(n^(1/e)) exactly
        if e == 2:
            root = math.isqrt(n)
        else:
            root = int(n**(1/e))
            # Adjust for potential float inaccuracies
            if (root + 1) ** e <= n:
                root += 1
            elif root ** e > n:
                root -= 1

        pp_count += -mu * (root - 1)

    # Achilles numbers are powerful numbers that are not perfect powers.
    # 1 is powerful but not Achilles, and not counted in pp_count.
    return powerful_count - pp_count - 1

from fractions import Fraction
from typing import Union

def simplest_between(lo: Union[int, Fraction], hi: Union[int, Fraction], 
                     lo_incl: bool = True, hi_incl: bool = True) -> Fraction:
    """
    Returns the simplest fraction in the interval [lo, hi] (or open/closed based on flags).
    Simplest means smallest denominator, then smallest absolute numerator.
    """
    # Type checking
    if not isinstance(lo_incl, bool) or not isinstance(hi_incl, bool):
        raise ValueError("lo_incl and hi_incl must be booleans")

    # lo and hi can be int or Fraction, but not bool, float, str, None
    # Note: bool is a subclass of int, so we must check bool first
    if isinstance(lo, bool) or isinstance(hi, bool):
        raise ValueError("lo and hi must be int or Fraction, not bool")
    if not isinstance(lo, (int, Fraction)) or not isinstance(hi, (int, Fraction)):
        raise ValueError("lo and hi must be int or Fraction")

    lo = Fraction(lo)
    hi = Fraction(hi)

    if lo > hi:
        raise ValueError("lo must be <= hi")

    if lo == hi:
        if not (lo_incl and hi_incl):
            raise ValueError("Interval is empty")
        return lo

    # Check if 0 is in the interval
    zero_in_interval = False
    if lo < 0 < hi:
        zero_in_interval = True
    elif lo == 0 and lo_incl:
        zero_in_interval = True
    elif hi == 0 and hi_incl:
        zero_in_interval = True

    if zero_in_interval:
        return Fraction(0)

    # If interval is negative
    if lo < 0:
        new_lo = -hi
        new_hi = -lo
        new_lo_incl = hi_incl
        new_hi_incl = lo_incl
        res = _simplest_positive(new_lo, new_hi, new_lo_incl, new_hi_incl)
        return -res
    else:
        # Interval is positive. 0 <= lo < hi.
        # Since 0 is not in interval (checked above), lo > 0.
        return _simplest_positive(lo, hi, lo_incl, hi_incl)

def _simplest_positive(lo: Fraction, hi: Fraction, lo_incl: bool, hi_incl: bool) -> Fraction:
    """
    Finds the simplest positive fraction in (lo, hi).
    Assumes 0 < lo < hi.
    Uses Stern-Brocot tree search to find the fraction with smallest denominator.
    """
    # L = a/b, R = c/d
    a, b = 0, 1
    c, d = 1, 0

    while True:
        m_num = a + c
        m_den = b + d

        # Compare M = m_num/m_den with lo and hi using cross-multiplication
        diff_lo = m_num * lo.den - lo.num * m_den
        diff_hi = m_num * hi.den - hi.num * m_den

        if diff_lo < 0:
            # M < lo
            a, b = m_num, m_den
        elif diff_lo > 0:
            # M > lo
            if diff_hi < 0:
                # lo < M < hi
                return Fraction(m_num, m_den)
            elif diff_hi == 0:
                # M == hi
                if hi_incl:
                    return Fraction(m_num, m_den)
                else:
                    c, d = m_num, m_den
            else:
                # M > hi
                c, d = m_num, m_den
        else:
            # M == lo
            if lo_incl:
                return Fraction(m_num, m_den)
            else:
                a, b = m_num, m_den

