from fractions import Fraction
import math

def simplest_between(lo, hi, lo_incl=True, hi_incl=True):
    # --- Input Validation ---

    # Check types for lo and hi
    if isinstance(lo, bool) or isinstance(hi, bool):
        raise ValueError("lo and hi must not be bool")
    if isinstance(lo, float) or isinstance(hi, float):
        raise ValueError("lo and hi must not be float")
    if isinstance(lo, str) or isinstance(hi, str):
        raise ValueError("lo and hi must not be str")
    if lo is None or hi is None:
        raise ValueError("lo and hi must not be None")
    if not isinstance(lo, (int, Fraction)) or not isinstance(hi, (int, Fraction)):
        raise ValueError("lo and hi must be int or Fraction")

    # Check types for flags
    if not isinstance(lo_incl, bool) or not isinstance(hi_incl, bool):
        raise ValueError("lo_incl and hi_incl must be bool")

    # Normalize to Fraction
    L = Fraction(lo)
    H = Fraction(hi)

    # Check order
    if L > H:
        raise ValueError("lo must be <= hi")

    # Check empty interval
    if L == H:
        if not (lo_incl and hi_incl):
            raise ValueError("Interval is empty")
        return L

    # --- Logic ---

    # 1. Check if 0 is in the interval
    # 0 is the simplest possible fraction (denom 1, num 0)
    if L <= 0 <= H:
        if (L == 0 and not lo_incl) or (H == 0 and not hi_incl):
            pass # 0 is excluded
        else:
            return Fraction(0)

    # 2. Check if any integer is in the interval
    # Integers have denominator 1, which is minimal possible for non-zero.
    # If multiple integers, pick one with smallest absolute value.
    # Since 0 is excluded, all integers have same sign.

    # Helper to check if integer k is in [L, H] with inclusivity
    def is_int_in_interval(k):
        if L < k < H:
            return True
        if L == k and lo_incl:
            return True
        if H == k and hi_incl:
            return True
        return False

    # Find range of integers
    # Lower bound for integer k
    if lo_incl:
        k_min = math.ceil(L)
    else:
        # strictly greater than L
        if L == int(L):
            k_min = int(L) + 1
        else:
            k_min = math.ceil(L)

    # Upper bound for integer k
    if hi_incl:
        k_max = math.floor(H)
    else:
        # strictly less than H
        if H == int(H):
            k_max = int(H) - 1
        else:
            k_max = math.floor(H)

    if k_min <= k_max:
        # Integers exist in interval
        # Pick integer with smallest absolute value
        if L > 0:
            # All positive, smallest is k_min
            return Fraction(k_min)
        else:
            # All negative, smallest absolute value is k_max (closest to 0)
            return Fraction(k_max)

    # 3. No integers in interval. Search for fraction with smallest denominator.
    # Since no integers, interval is strictly inside (floor(L), floor(L)+1) or similar.
    # We can work with positive fractions by mapping if necessary.

    if H < 0:
        # Interval is negative. Map to positive interval [-H, -L].
        # Invert inclusivity for bounds.
        # x in [L, H] <=> -x in [-H, -L]
        # L <= x <= H <=> -H <= -x <= -L
        # L inclusive <=> -L inclusive (upper bound of new interval)
        # H inclusive <=> -H inclusive (lower bound of new interval)
        pos_lo = -H
        pos_hi = -L
        pos_lo_incl = hi_incl
        pos_hi_incl = lo_incl
        result = _simplest_positive(pos_lo, pos_hi, pos_lo_incl, pos_hi_incl)
        return -result
    else:
        # Interval is positive (since 0 excluded and not negative)
        return _simplest_positive(L, H, lo_incl, hi_incl)

def _simplest_positive(lo, hi, lo_incl, hi_incl):
    """
    Finds simplest positive fraction in [lo, hi].
    Assumes lo > 0, hi > 0, and no integers in interval.
    """
    # Use Stern-Brocot tree search
    # We maintain bounds left = a/b, right = c/d such that lo <= a/b < c/d <= hi?
    # Actually, we maintain a current interval of fractions [L_frac, R_frac] that contains the target.
    # Initially, we can bound the search.
    # But simpler: start with 0/1 and 1/0 (infinity) and narrow down.

    # However, since we know lo > 0, we can start with left = 0/1, right = 1/0.
    # But 1/0 is infinity.

    left_n, left_d = 0, 1
    right_n, right_d = 1, 0 # Represents infinity

    while True:
        # Mediant
        mid_n = left_n + right_n
        mid_d = left_d + right_d
        mid = Fraction(mid_n, mid_d)

        # Check if mid is in [lo, hi]
        in_interval = False
        if mid > lo and mid < hi:
            in_interval = True
        elif mid == lo and lo_incl:
            in_interval = True
        elif mid == hi and hi_incl:
            in_interval = True

        if in_interval:
            return mid

        # Decide direction
        if mid < lo:
            # Target is to the right
            left_n, left_d = mid_n, mid_d
        else:
            # mid > hi, target is to the left
            right_n, right_d = mid_n, mid_d

        # Safety break (should not happen for valid rational bounds)
        if mid_d > 10**18: 
            # Should not be reached if logic is correct
            break

