    if not isinstance(lo_incl, bool) or not isinstance(hi_incl, bool):
        raise ValueError("lo_incl and hi_incl must be bool")

    L = Fraction(lo)
    H = Fraction(hi)

    if L > H:
        raise ValueError("lo must be <= hi")
    if L == H:
        if not (lo_incl and hi_incl):
            raise ValueError("Interval is empty")
        return L

    # --- Handle 0 ---
    if L <= 0 <= H:
        if (L == 0 and not lo_incl) or (H == 0 and not hi_incl):
            pass
        else:
            return Fraction(0)

    # --- Handle Integers ---
    def is_int_in_interval(k):
        if L < k < H: return True
        if L == k and lo_incl: return True
        if H == k and hi_incl: return True
        return False

    if lo_incl:
        k_min = math.ceil(L)
    else:
        k_min = int(L) + 1 if L == int(L) else math.ceil(L)
    if hi_incl:
        k_max = math.floor(H)
    else:
        k_max = int(H) - 1 if H == int(H) else math.floor(H)

    if k_min <= k_max:
        if L > 0:
            return Fraction(k_min)
        elif H < 0:
            return Fraction(k_max)
        else:
            # Interval crosses 0 but 0 excluded? Handled above.
            # If we are here, 0 is excluded, so all integers have same sign.
            # But L <= 0 <= H and 0 excluded means L < 0 < H.
            # k_min <= 0 <= k_max. Smallest abs is 0, but excluded.
            # So pick k_min if k_min > 0 else k_max.
            if k_min > 0:
                return Fraction(k_min)
            else:
                return Fraction(k_max)

    # --- Map to Positive Interval ---
    if H < 0:
        pos_lo = -H
        pos_hi = -L
        pos_lo_incl = hi_incl
        pos_hi_incl = lo_incl
        return -_simplest_positive(pos_lo, pos_hi, pos_lo_incl, pos_hi_incl)
    else:
        return _simplest_positive(L, H, lo_incl, hi_incl)

def _simplest_positive(lo, hi, lo_incl, hi_incl):
    # Assumes 0 < lo < hi and no integers in interval.
    # Use continued fraction expansion to find simplest fraction.

    def cf(f):
        res = []
        while f.denominator != 0:
            a = f.numerator // f.denominator
            res.append(a)
            f = f - a
            if f == 0:
                break
            f = Fraction(1, 1) / f
        return res

    def from_cf(cf_list):
        if not cf_list:
            return Fraction(0)
        num, den = 1, 0
        for a in reversed(cf_list):
            num, den = den, num
            num += a * den
        return Fraction(num, den)

    cf_L = cf(lo)
    cf_H = cf(hi)

    # Find first index where they differ
    i = 0
    while i < len(cf_L) and i < len(cf_H) and cf_L[i] == cf_H[i]:
        i += 1

    if i == len(cf_L) or i == len(cf_H):
        # One is a prefix of the other. The shorter one is in the interval and simplest.
        best_cf = min(cf_L, cf_H, key=len)
        return from_cf(best_cf)

    # They differ at index i
    if cf_L[i] > cf_H[i]:
        cf_L, cf_H = cf_H, cf_L
        lo, hi = hi, lo
        lo_incl, hi_incl = hi_incl, lo_incl

    # Now cf_L[i] < cf_H[i]
    # Candidate 1: extend L's CF with cf_L[i] + 1
    cand1_cf = cf_L[:i] + [cf_L[i] + 1]
    cand1 = from_cf(cand1_cf)

    # We need to check if cand1 is within [lo, hi] respecting inclusivity.
    # Since cand1 > lo always (because cf_L[i]+1 > cf_L[i]), we only check upper bound.
    in_cand1 = False
    if cand1 < hi:
        in_cand1 = True
    elif cand1 == hi and hi_incl:
        in_cand1 = True

    if in_cand1:
        return cand1

    # If cand1 > hi, the simplest fraction must be deeper.
    # It will have CF: cf_L[:i] + [cf_L[i], min(cf_L[i+1], cf_H[i+1]) + 1]
    next_L = cf_L[i+1] if i+1 < len(cf_L) else float('inf')
    next_H = cf_H[i+1] if i+1 < len(cf_H) else float('inf')
    cand2_cf = cf_L[:i] + [cf_L[i], min(next_L, next_H) + 1]
    return from_cf(cand2_cf)

