    if not isinstance(lo_incl, bool) or not isinstance(hi_incl, bool):
        raise ValueError("lo_incl and hi_incl must be bool")

    lo = Fraction(lo)
    hi = Fraction(hi)

    if lo > hi:
        raise ValueError("lo must be <= hi")
    if lo == hi and not (lo_incl and hi_incl):
        raise ValueError("Interval is empty")

    if lo == hi:
        return lo

    # Check for integers in the interval
    if lo_incl:
        int_lo = lo
    else:
        int_lo = lo + 1

    if hi_incl:
        int_hi = hi
    else:
        int_hi = hi - 1

    if int_lo <= int_hi:
        if int_lo <= 0 <= int_hi:
            return Fraction(0)
        elif abs(int_lo) <= abs(int_hi):
            return Fraction(int_lo)
        else:
            return Fraction(int_hi)

    # Shift to (0, 1)
    shift = lo.to_integral_value(rounding=math.ROUND_FLOOR)
    lo -= shift
    hi -= shift
    # Now 0 < lo < hi < 1

    a, b = 0, 1
    c, d = 1, 0

    while True:
        val_lo = (lo * b - a) / (c - lo * d)
        val_hi = (hi * b - a) / (c - hi * d)

        if lo_incl:
            k_lo = val_lo.__ceil__()
        else:
            k_lo = val_lo.__floor__() + 1

        if hi_incl:
            k_hi = val_hi.__floor__()
        else:
            k_hi = val_hi.__ceil__() - 1

        if k_lo < 1:
            k_lo = 1
        if k_hi < 1:
            k_hi = 0

        if k_lo <= k_hi:
            k = k_lo
            res = Fraction(a + k * c, b + k * d)
            return res + shift
        else:
            k_update = max(1, k_hi)
            c, d = a + k_update * c, b + k_update * d

