        raise ValueError("lo_incl and hi_incl must be bool")
    if type(lo) is bool or type(hi) is bool:
        raise ValueError("lo and hi must not be bool")
    if not isinstance(lo, (int, Fraction)) or not isinstance(hi, (int, Fraction)):
        raise ValueError("lo and hi must be int or Fraction")

    lo = Fraction(lo)
    hi = Fraction(hi)

    if lo > hi:
        raise ValueError("lo must be <= hi")
    if lo == hi and not (lo_incl and hi_incl):
        raise ValueError("Interval is empty")

    # Check if 0 is in the interval
    zero_in = (lo_incl and lo == 0) or (hi_incl and hi == 0) or (lo < 0 < hi)
    if zero_in:
        return Fraction(0)

    # Handle negative interval by symmetry
    if lo < 0 and hi < 0:
        lo, hi = -hi, -lo
        lo_incl, hi_incl = hi_incl, lo_incl
        # Now 0 < lo < hi
        res = _simplest_positive(lo, hi, lo_incl, hi_incl)
        return Fraction(-res.numerator, res.denominator)
    else:
        # 0 < lo < hi
        return _simplest_positive(lo, hi, lo_incl, hi_incl)

def _simplest_positive(lo, hi, lo_incl, hi_incl):
    # Stern-Brocot search for the fraction with smallest denominator in [lo, hi]
    l_num, l_den = 0, 1
    r_num, r_den = 1, 0

    while True:
        m_num = l_num + r_num
        m_den = l_den + r_den

        # Compare m = m_num/m_den with lo and hi using cross-multiplication
        cmp_lo = m_num * lo.denominator - lo.numerator * m_den
        cmp_hi = m_num * hi.denominator - hi.numerator * m_den

        if cmp_lo < 0:
            # m < lo, move left bound up
            l_num, l_den = m_num, m_den
        elif cmp_hi > 0:
            # m > hi, move right bound down
            r_num, r_den = m_num, m_den
        else:
            # lo <= m <= hi
            if cmp_lo == 0 and not lo_incl:
                l_num, l_den = m_num, m_den
            elif cmp_hi == 0 and not hi_incl:
                r_num, r_den = m_num, m_den
            else:
                return Fraction(m_num, m_den)

def square_roots_mod(a: int, n: int) -> int:
    # Input validation
    # Check types explicitly to exclude bool
    if type(a) is not int or type(n) is not int:
        raise ValueError("Inputs must be integers")
    if n < 1 or n > 10**10:
        raise ValueError("n must be between 1 and 10^10")
    if abs(a) > 10**18:
        raise ValueError("abs(a) must be <= 10^18")

    if n == 1:
        return 1

    # Factorize n
    # Since n <= 10^10, we can trial divide up to 10^5
    factors = {}
    temp_n = n
    d = 2
    # Optimization: check 2 separately to skip even numbers
    if temp_n % 2 == 0:
        count = 0
        while temp_n % 2 == 0:
            count += 1
            temp_n //= 2
        factors[2] = count

    d = 3
    while d * d <= temp_n:
        if temp_n % d == 0:
            count = 0
            while temp_n % d == 0:
                count += 1
                temp_n //= d
            factors[d] = count
        d += 2
    if temp_n > 1:
        factors[temp_n] = 1

    total_solutions = 1

    for p, e in factors.items():
        mod_p_e = p ** e
        a_mod = a % mod_p_e

        if p == 2:
            count = count_solutions_mod_2_pow_e(a_mod, e)
        else:
            count = count_solutions_mod_odd_prime_pow(a_mod, p, e)

        total_solutions *= count
        if total_solutions == 0:
            return 0

    return total_solutions

def count_solutions_mod_odd_prime_pow(a_mod, p, e):
    # Solve x^2 == a_mod (mod p^e) for odd prime p
    # a_mod is already reduced modulo p^e

    # Case 1: a_mod == 0
    if a_mod == 0:
        # x^2 = 0 (mod p^e) => x is multiple of p^ceil(e/2)
        # Number of multiples is p^e / p^ceil(e/2) = p^floor(e/2)
        return p ** (e // 2)

    # Case 2: a_mod != 0
    # Let v = v_p(a_mod). If v is odd, no solution.
    # If v is even, say v = 2j, then x^2 = p^(2j) * u (mod p^e)
    # => (x/p^j)^2 = u (mod p^(e-2j)) where u is not divisible by p.

    # Calculate valuation
    v = 0
    temp_a = a_mod
    while temp_a % p == 0:
        v += 1
        temp_a //= p

    if v % 2 == 1:
        return 0

    j = v // 2
    u = temp_a
    m = e - 2 * j  # New modulus exponent for u

    # We need to solve y^2 == u (mod p^m) where gcd(u, p) = 1
    # This is equivalent to checking if u is a quadratic residue mod p
    # If yes, there are 2 solutions mod p^m.
    # The number of solutions for x is 2 * p^j.

    u_mod_p = u % p
    if u_mod_p == 0: 
        return 0 

    # Check quadratic residue
    if pow(u_mod_p, (p - 1) // 2, p) == 1:
        return 2 * (p ** j)
    else:
        return 0

def count_solutions_mod_2_pow_e(a_mod, e):
    # Solve x^2 == a_mod (mod 2^e)
    # a_mod is already reduced modulo 2^e

    if e == 1:
        # mod 2
        # x^2 = x (mod 2). x = a_mod (mod 2). Always 1 solution.
        return 1

    if e == 2:
        # mod 4
        # Squares mod 4 are 0, 1.
        rem = a_mod % 4
        if rem == 0 or rem == 1:
            return 2
        else:
            return 0

    # e >= 3
    if a_mod == 0:
        # x^2 = 0 (mod 2^e)
        # x is multiple of 2^ceil(e/2)
        # Count = 2^(e - ceil(e/2)) = 2^floor(e/2)
        return 2 ** (e // 2)

    # Find valuation of 2 in a_mod
    k = 0
    temp_a = a_mod
    while temp_a % 2 == 0:
        k += 1
        temp_a //= 2

    u = temp_a # u is odd

    if k >= e:
        # a_mod is 0 mod 2^e, handled above
        return 2 ** (e // 2)

    if k % 2 == 1:
        # Odd valuation, no solution
        return 0

    j = k // 2
    # We need to solve y^2 == u (mod 2^(e - 2j))
    # Let m = e - 2j. u is odd.
    m = e - 2 * j

    # Count solutions for y^2 == u (mod 2^m) with u odd
    # If m = 1 (mod 2), 1 solution (y=1)
    # If m = 2 (mod 4), 2 solutions if u=1 mod 4, else 0
    # If m >= 3 (mod 8), 4 solutions if u=1 mod 8, else 0

    num_solutions_y = 0
    if m == 1:
        num_solutions_y = 1
    elif m == 2:
        if u % 4 == 1:
            num_solutions_y = 2
        else:
            num_solutions_y = 0
    else: # m >= 3
        if u % 8 == 1:
            num_solutions_y = 4
        else:
            num_solutions_y = 0

    # Each solution y mod 2^m lifts to 2^j solutions for x mod 2^e
    return num_solutions_y * (2 ** j)

def hull_peel_layers(points):
    if not isinstance(points, (list, tuple)):
        raise ValueError
    if len(points) > 2000:
        raise ValueError
    if len(points) == 0:
        return 0

    valid_points = []
    for p in points:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError
        x, y = p
        if isinstance(x, bool) or isinstance(y, bool):
            raise ValueError
        if not isinstance(x, int) or not isinstance(y, int):
            raise ValueError
        if not (-10**9 <= x <= 10**9 and -10**9 <= y <= 10**9):
            raise ValueError
        valid_points.append((x, y))

    S = valid_points
    layers = 0

    def cross_product(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

    def on_segment(p, a, b):
        if cross_product(a, b, p) != 0:
            return False
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    while S:
        layers += 1
        unique_S = list(set(S))
        if len(unique_S) == 1:
            S = []
            continue

        p1, p2 = unique_S[0], unique_S[1]
        is_collinear = True
        for p in unique_S[2:]:
            if cross_product(p1, p2, p) != 0:
                is_collinear = False
                break
        if is_collinear:
            S = []
            continue

        pts = sorted(unique_S)
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross_product(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross_product(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        hull = lower[:-1] + upper[:-1]

        new_S = []
        m = len(hull)
        for p in S:
            is_boundary = False
            for i in range(m):
                if on_segment(p, hull[i], hull[(i+1)%m]):
                    is_boundary = True
                    break
            if not is_boundary:
                new_S.append(p)
        S = new_S

    return layers

def circ_exact_count(a, queries):
    # Validate a
    if not isinstance(a, (list, tuple)):
        raise ValueError("a must be a list or tuple")

    n = len(a)
    if not (1 <= n <= 3000):
        raise ValueError("Length of a must be between 1 and 3000")

    # Check elements of a
    limit = 10**9
    for x in a:
        # bool is a subclass of int, but prompt says bool is not an int
        if type(x) is not int:
            raise ValueError("Elements of a must be ints")
        if abs(x) > limit:
            raise ValueError("Elements of a out of range")

    # Validate queries
    if not isinstance(queries, (list, tuple)):
        raise ValueError("queries must be a list or tuple")

    if len(queries) > 3000:
        raise ValueError("Too many queries")

    result = []

    for item in queries:
        # Check if item is a list or tuple
        if type(item) is not list and type(item) is not tuple:
            raise ValueError("Each query must be a list or tuple")
        if len(item) != 3:
            raise ValueError("Each query must have 3 elements")

        l, r, k = item

        # Check types for l, r, k
        if type(l) is not int or type(r) is not int or type(k) is not int:
            raise ValueError("l, r, k must be ints")

        # Check ranges
        if not (0 <= l < n):
            raise ValueError("l out of range")
        if not (0 <= r < n):
            raise ValueError("r out of range")
        if not (1 <= k <= n):
            raise ValueError("k out of range")

        # Determine window
        if l <= r:
            # Window is a[l], ..., a[r]
            window = a[l : r + 1]
        else:
            # Window is a[l], ..., a[n-1], a[0], ..., a[r]
            window = a[l:] + a[:r + 1]

        # Count frequencies
        counts = {}
        for val in window:
            if val in counts:
                counts[val] += 1
            else:
                counts[val] = 1

        # Count how many values appear exactly k times
        ans = 0
        for c in counts.values():
            if c == k:
                ans += 1

        result.append(ans)

    return result

import bisect

def staircase_log(points):
    if not isinstance(points, (list, tuple)):
        raise ValueError
    for p in points:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError
        if not all(isinstance(c, int) and not isinstance(c, bool) for c in p):
            raise ValueError

    flags = []
    front = []
    front_x = []

    for p in points:
        px, py = p
        idx = bisect.bisect_left(front_x, px)

        dominated = False
        if idx < len(front):
            if front[idx][0] > px or front[idx][1] > py:
                dominated = True
            elif front[idx][0] == px and front[idx][1] == py:
                flags.append(True)
                continue

        flags.append(not dominated)

        if not dominated:
            while idx > 0 and front[idx-1][1] <= py:
                idx -= 1
                front.pop()
                front_x.pop()

            front.insert(idx, tuple(p))
            front_x.insert(idx, px)

    return flags, tuple(front)

def segment_pair_kinds(segs):
    # Validation
    if not isinstance(segs, (list, tuple)):
        raise ValueError("segs must be a list or tuple")
    if len(segs) > 2000:
        raise ValueError("segs must have at most 2000 items")
    for s in segs:
        if not isinstance(s, (list, tuple)) or len(s) != 4:
            raise ValueError("Each segment must be a list or tuple of 4 coordinates")
        for coord in s:
            if isinstance(coord, bool) or not isinstance(coord, int):
                raise ValueError("Coordinates must be integers")
            if abs(coord) > 10**9:
                raise ValueError("Coordinates must be within |10^9|")

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def point_on_segment(p, a, b):
        # Check if p lies on segment ab
        if cross_product(a, b, p) != 0:
            return False
        # Bounding box check
        if min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and \
           min(a[1], b[1]) <= p[1] <= max(a[1], b[1]):
            return True
        return False

    cross_count = 0
    touch_count = 0
    overlap_count = 0

    n = len(segs)
    for i in range(n):
        x1, y1, x2, y2 = segs[i]
        p1 = (x1, y1)
        p2 = (x2, y2)
        is_p1 = (p1 == p2)

        for j in range(i + 1, n):
            x3, y3, x4, y4 = segs[j]
            q1 = (x3, y3)
            q2 = (x4, y4)
            is_q1 = (q1 == q2)

            # Case 1: Both point segments
            if is_p1 and is_q1:
                if p1 == q1:
                    touch_count += 1
                continue

            # Case 2: One point, one segment
            if is_p1:
                # S1 is point p1, S2 is segment q1-q2
                if point_on_segment(p1, q1, q2):
                    touch_count += 1
                continue
            if is_q1:
                # S1 is segment p1-p2, S2 is point q1
                if point_on_segment(q1, p1, p2):
                    touch_count += 1
                continue

            # Case 3: Both non-degenerate
            # Check collinearity
            cp1 = cross_product(p1, p2, q1)
            cp2 = cross_product(p1, p2, q2)

            if cp1 == 0 and cp2 == 0:
                # Collinear
                # Project to axis with non-zero length
                if x1 != x2:
                    min1, max1 = (x1, x2) if x1 < x2 else (x2, x1)
                    min2, max2 = (x3, x4) if x3 < x4 else (x4, x3)
                else:
                    min1, max1 = (y1, y2) if y1 < y2 else (y2, y1)
                    min2, max2 = (y3, y4) if y3 < y4 else (y4, y3)

                inter_min = max(min1, min2)
                inter_max = min(max1, max2)

                if inter_min > inter_max:
                    pass # Empty
                elif inter_min == inter_max:
                    touch_count += 1
                else:
                    overlap_count += 1
            else:
                # Not collinear
                # Check shared endpoints
                if p1 == q1 or p1 == q2 or p2 == q1 or p2 == q2:
                    touch_count += 1
                    continue

                # Check if any endpoint lies strictly inside the other segment
                # Since endpoints are distinct, point_on_segment implies strictly inside
                if point_on_segment(q1, p1, p2) or \
                   point_on_segment(q2, p1, p2) or \
                   point_on_segment(p1, q1, q2) or \
                   point_on_segment(p2, q1, q2):
                    touch_count += 1
                    continue

                # Check strict crossing
                cp3 = cross_product(q1, q2, p1)
                cp4 = cross_product(q1, q2, p2)

                if (cp1 * cp2 < 0) and (cp3 * cp4 < 0):
                    cross_count += 1

    return (cross_count, touch_count, overlap_count)

def bridge_free_labels(n, edges):
    if not isinstance(n, int) or n < 1 or n > 200000:
        raise ValueError("n out of range")
    if not hasattr(edges, '__iter__'):
        raise ValueError("edges must be iterable")

    adj = [[] for _ in range(n)]
    num_edges = 0
    for item in edges:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("Invalid edge format")
        u, v = item
        if not isinstance(u, int) or isinstance(u, bool) or not isinstance(v, int) or isinstance(v, bool):
            raise ValueError("Edge vertices must be ints")
        if not (0 <= u < n and 0 <= v < n):
            raise ValueError("Edge vertices out of range")
        adj[u].append((v, num_edges))
        adj[v].append((u, num_edges))
        num_edges += 1

    disc = [-1] * n
    low = [-1] * n
    timer = 0
    stack = []
    is_bridge = [False] * num_edges

    for i in range(n):
        if disc[i] == -1:
            stack.append((i, iter(adj[i]), -1))
            disc[i] = low[i] = timer
            timer += 1
            while stack:
                u, neighbors, parent_edge_idx = stack[-1]
                edge_idx = parent_edge_idx
                try:
                    v, edge_idx = next(neighbors)
                    if edge_idx == parent_edge_idx:
                        continue
                    if disc[v] != -1:
                        low[u] = min(low[u], disc[v])
                    else:
                        disc[v] = low[v] = timer
                        timer += 1
                        stack.append((v, iter(adj[v]), edge_idx))
                except StopIteration:
                    stack.pop()
                    if stack:
                        parent_u = stack[-1][0]
                        low[parent_u] = min(low[parent_u], low[u])
                        if low[u] > disc[parent_u]:
                            is_bridge[edge_idx] = True

    label = [-1] * n
    comp_id = 0
    for i in range(n):
        if label[i] == -1:
            label[i] = comp_id
            queue = [i]
            head = 0
            while head < len(queue):
                u = queue[head]
                head += 1
                for v, e_idx in adj[u]:
                    if label[v] == -1 and not is_bridge[e_idx]:
                        label[v] = comp_id
                        queue.append(v)
            comp_id += 1

    return label

def bridge_free_labels(n, edges):
    # Validate n
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 1 or n > 200000:
        raise ValueError("n out of range")

    # Validate edges
    if not hasattr(edges, '__iter__'):
        raise ValueError("edges must be iterable")

    adj = [[] for _ in range(n)]
    num_edges = 0
    for item in edges:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("Invalid edge format")
        u, v = item
        # Check int but not bool
        if isinstance(u, bool) or not isinstance(u, int):
            raise ValueError("Edge vertices must be integers")
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError("Edge vertices must be integers")
        if not (0 <= u < n) or not (0 <= v < n):
            raise ValueError("Edge vertices out of range")

        adj[u].append((v, num_edges))
        adj[v].append((u, num_edges))
        num_edges += 1

    disc = [-1] * n
    low = [-1] * n
    timer = 0
    is_bridge = [False] * num_edges

    for i in range(n):
        if disc[i] == -1:
            # Iterative DFS
            # Stack elements: (u, iterator, parent_edge_idx)
            stack = [(i, iter(adj[i]), -1)]
            disc[i] = low[i] = timer
            timer += 1

            while stack:
                u, neighbors, parent_edge_idx = stack[-1]

                try:
                    v, edge_idx = next(neighbors)
                except StopIteration:
                    stack.pop()
                    if stack:
                        parent_u = stack[-1][0]
                        low[parent_u] = min(low[parent_u], low[u])
                        if low[u] > disc[parent_u]:
                            is_bridge[parent_edge_idx] = True
                    continue

                if edge_idx == parent_edge_idx:
                    continue

                if disc[v] != -1:
                    # Back edge
                    low[u] = min(low[u], disc[v])
                else:
                    # Tree edge
                    disc[v] = low[v] = timer
                    timer += 1
                    stack.append((v, iter(adj[v]), edge_idx))

    label = [-1] * n
    comp_id = 0

    for i in range(n):
        if label[i] == -1:
            # BFS to find component
            label[i] = comp_id
            queue = [i]
            head = 0
            while head < len(queue):
                u = queue[head]
                head += 1
                for v, e_idx in adj[u]:
                    if label[v] == -1 and not is_bridge[e_idx]:
                        label[v] = comp_id
                        queue.append(v)
            comp_id += 1

    return label

import re

def run_regvm8(program, regs, max_steps):
    # 1. Input Validation
    if not isinstance(program, list):
        raise ValueError("program must be a list")
    if not isinstance(regs, dict):
        raise ValueError("regs must be a dict")
    if isinstance(max_steps, bool) or not isinstance(max_steps, int):
        raise ValueError("max_steps must be an int")
    if not (0 <= max_steps <= 10**6):
        raise ValueError("max_steps out of range")

    for k, v in regs.items():
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError("regs values must be ints")
        if not (0 <= v <= 255):
            raise ValueError("regs values out of range")

    # 2. Parsing
    label_re = re.compile(r'^[a-z_][a-z0-9_]*$')
    reg_re = re.compile(r'^[a-z]$')

    instructions = []
    labels = {}
    current_instr_idx = 0

    for line in program:
        # Strip comments
        if ';' in line:
            line = line[:line.index(';')]

        tokens = line.split()
        if not tokens:
            continue

        # Check for label
        if tokens[0].endswith(':'):
            if len(tokens) != 1:
                raise ValueError("Bad label name (label plus instruction on one line)")

            name = tokens[0][:-1]
            if not label_re.match(name):
                raise ValueError(f"Bad label name '{name}'")

            if name in labels:
                raise ValueError(f"Duplicated label '{name}'")

            labels[name] = current_instr_idx
            continue

        # It's an instruction
        opcode = tokens[0]
        args = tokens[1:]

        if opcode not in ('INC', 'DEC', 'ADD', 'JZ', 'JNZ', 'JMP', 'CALL', 'RET', 'HALT'):
            raise ValueError(f"Unknown opcode '{opcode}'")

        parsed_args = []

        if opcode == 'INC':
            if len(args) != 1: raise ValueError("INC needs 1 operand")
            if not reg_re.match(args[0]):
                raise ValueError("INC operand must be register")
            parsed_args.append(('reg', args[0]))

        elif opcode == 'DEC':
            if len(args) != 1: raise ValueError("DEC needs 1 operand")
            if not reg_re.match(args[0]):
                raise ValueError("DEC operand must be register")
            parsed_args.append(('reg', args[0]))

        elif opcode == 'ADD':
            if len(args) != 2: raise ValueError("ADD needs 2 operands")
            for arg in args:
                if not reg_re.match(arg):
                    raise ValueError("ADD operands must be registers")
            parsed_args.append(('reg', args[0]))
            parsed_args.append(('reg', args[1]))

        elif opcode in ('JZ', 'JNZ'):
            if len(args) != 2: raise ValueError(f"{opcode} needs 2 operands")
            if not reg_re.match(args[0]):
                raise ValueError(f"{opcode} first operand must be register")
            if not label_re.match(args[1]):
                raise ValueError(f"{opcode} second operand bad label syntax")
            parsed_args.append(('reg', args[0]))
            parsed_args.append(('label', args[1]))

        elif opcode == 'JMP':
            if len(args) != 1: raise ValueError("JMP needs 1 operand")
            if not label_re.match(args[0]):
                raise ValueError("JMP operand bad label syntax")
            parsed_args.append(('label', args[0]))

        elif opcode == 'CALL':
            if len(args) != 1: raise ValueError("CALL needs 1 operand")
            if not label_re.match(args[0]):
                raise ValueError("CALL operand bad label syntax")
            parsed_args.append(('label', args[0]))

        elif opcode == 'RET':
            if len(args) != 0: raise ValueError("RET needs 0 operands")

        elif opcode == 'HALT':
            if len(args) != 0: raise ValueError("HALT needs 0 operands")

        instructions.append((opcode, parsed_args))
        current_instr_idx += 1

    # 3. Validate Labels
    for opcode, args in instructions:
        if opcode in ('JZ', 'JNZ', 'JMP', 'CALL'):
            for arg_type, arg_val in args:
                if arg_type == 'label':
                    if arg_val not in labels:
                        raise ValueError(f"Undefined label '{arg_val}'")

    # 4. Prepare Registers
    used_regs = set()
    for opcode, args in instructions:
        for arg_type, arg_val in args:
            if arg_type == 'reg':
                used_regs.add(arg_val)

    final_regs = {}
    for k in regs:
        final_regs[k] = regs[k]
    for r in used_regs:
        if r not in final_regs:
            final_regs[r] = 0

    # 5. Execution
    pc = 0
    steps = 0
    stack = []
    num_instructions = len(instructions)

    # Helper to get register value
    def get_reg(r):
        return final_regs[r]

    # Helper to set register value
    def set_reg(r, val):
        final_regs[r] = val

    while True:
        # Check termination conditions before execution
        if pc >= num_instructions:
            return ("halt", steps, final_regs)

        if steps == max_steps:
            return ("limit", steps, final_regs)

        # Execute instruction
        opcode, args = instructions[pc]

        if opcode == 'INC':
            r = args[0][1]
            val = (get_reg(r) + 1) % 256
            set_reg(r, val)
            pc += 1

        elif opcode == 'DEC':
            r = args[0][1]
            val = (get_reg(r) - 1) % 256
            set_reg(r, val)
            pc += 1

        elif opcode == 'ADD':
            r = args[0][1]
            s = args[1][1]
            val = (get_reg(r) + get_reg(s)) % 256
            set_reg(r, val)
            pc += 1

        elif opcode == 'JZ':
            r = args[0][1]
            L = args[1][1]
            if get_reg(r) == 0:
                pc = labels[L]
            else:
                pc += 1

        elif opcode == 'JNZ':
            r = args[0][1]
            L = args[1][1]
            if get_reg(r) != 0:
                pc = labels[L]
            else:
                pc += 1

        elif opcode == 'JMP':
            L = args[0][1]
            pc = labels[L]

        elif opcode == 'CALL':
            L = args[0][1]
            if len(stack) == 8:
                steps += 1
                return ("fault", steps, final_regs)
            stack.append(pc + 1)
            pc = labels[L]

        elif opcode == 'RET':
            if not stack:
                pc += 1 # Effectively halt? No, prompt says "with an empty call stack the machine halts"
                # But PC increment is not specified for RET on empty stack.
                # "RET ... with an empty call stack the machine halts"
                # Usually means stop. Let's check loop condition.
                # If we just return, we need to ensure steps is correct.
                # The instruction is executed.
                # So steps increments.
                # Then loop checks pc >= len?
                # If we set pc to something >= len, it halts.
                # Or just return.
                steps += 1
                return ("halt", steps, final_regs)
            else:
                pc = stack.pop()

        elif opcode == 'HALT':
            steps += 1
            return ("halt", steps, final_regs)

        steps += 1

