def mlfq_finish_times(jobs, quanta):
    # Validate inputs
    if not isinstance(jobs, list) or not isinstance(quanta, list):
        raise ValueError("Invalid input types")
    if len(quanta) < 1 or len(quanta) > 5:
        raise ValueError("quanta must have 1 to 5 elements")
    for q in quanta:
        if not isinstance(q, int) or q < 1 or q > 10**4:
            raise ValueError("quanta elements must be integers between 1 and 10000")

    for job in jobs:
        if not isinstance(job, (list, tuple)) or len(job) != 2:
            raise ValueError("Each job must be a pair of ints")
        if not isinstance(job[0], int) or not isinstance(job[1], int):
            raise ValueError("Job arrival and burst must be integers")
        if job[0] < 0 or job[0] > 10**6:
            raise ValueError("Arrival time out of range")
        if job[1] < 1 or job[1] > 10**4:
            raise ValueError("Burst time out of range")

    n = len(jobs)
    job_objects = []
    for i in range(n):
        job_objects.append({
            'id': i,
            'arrival': jobs[i][0],
            'burst': jobs[i][1],
            'remaining': jobs[i][1],
            'level': 0,
            'finish': None
        })

    queues = [[] for _ in quanta]
    current_time = 0
    job_ptr = 0
    running_job = None
    num_levels = len(quanta)

    while job_ptr < n or any(queues) or running_job is not None:
        if running_job is None:
            picked = False
            for l in range(num_levels):
                if queues[l]:
                    running_job = queues[l].pop(0)
                    picked = True
                    break

            if not picked:
                if job_ptr < n:
                    next_arrival = job_objects[job_ptr]['arrival']
                    if current_time < next_arrival:
                        current_time = next_arrival
                    while job_ptr < n and job_objects[job_ptr]['arrival'] == current_time:
                        queues[0].append(job_objects[job_ptr])
                        job_ptr += 1
                    continue
                else:
                    break
        else:
            job = running_job
            level = job['level']
            rem = job['remaining']
            quantum = quanta[level]

            duration = min(rem, quantum)
            end_time = current_time + duration

            preempted = False
            preempt_time = None

            if level >= 1 and job_ptr < n:
                arr_time = job_objects[job_ptr]['arrival']
                if current_time < arr_time < end_time:
                    preempted = True
                    preempt_time = arr_time

            if preempted:
                delta = preempt_time - current_time
                current_time = preempt_time
                job['remaining'] -= delta
                queues[level].insert(0, job)

                while job_ptr < n and job_objects[job_ptr]['arrival'] == current_time:
                    queues[0].append(job_objects[job_ptr])
                    job_ptr += 1

                running_job = None
            else:
                current_time = end_time
                job['remaining'] -= duration

                if job['remaining'] == 0:
                    job['finish'] = current_time
                    running_job = None
                    while job_ptr < n and job_objects[job_ptr]['arrival'] == current_time:
                        queues[0].append(job_objects[job_ptr])
                        job_ptr += 1
                else:
                    next_level = min(level + 1, num_levels - 1)
                    job['level'] = next_level

                    while job_ptr < n and job_objects[job_ptr]['arrival'] == current_time:
                        queues[0].append(job_objects[job_ptr])
                        job_ptr += 1

                    queues[next_level].append(job)
                    running_job = None

    results = [None] * n
    for job in job_objects:
        results[job['id']] = job['finish']

    return results

import bisect

def sim_best_fit_heap(size, ops):
    # Validation of size
    if not isinstance(size, int) or isinstance(size, bool):
        raise ValueError("size must be an integer")
    if size < 8 or size > 10**12 or size % 8 != 0:
        raise ValueError("size must be between 8 and 10^12 and a multiple of 8")

    if not isinstance(ops, list):
        raise ValueError("ops must be a list")

    allocated = {}  # id -> (addr, size)
    free_blocks = [(0, size)]  # list of (addr, size), sorted by addr

    results = []

    def round_up(n):
        return (n + 7) // 8 * 8

    def insert_free(addr, size):
        # Insert (addr, size) into free_blocks and coalesce with neighbors
        # free_blocks is sorted by address
        idx = bisect.bisect_left(free_blocks, (addr, 0))

        # Check merge with left neighbor
        if idx > 0:
            prev_addr, prev_size = free_blocks[idx-1]
            if prev_addr + prev_size == addr:
                # Merge with left
                free_blocks[idx-1] = (prev_addr, prev_size + size)
                # Now check if the merged block merges with the right neighbor (at idx)
                # Note: if idx == len(free_blocks), there is no right neighbor
                if idx < len(free_blocks):
                    curr_addr, curr_size = free_blocks[idx-1]
                    next_addr, next_size = free_blocks[idx]
                    if curr_addr + curr_size == next_addr:
                        # Merge with right
                        free_blocks[idx-1] = (curr_addr, curr_size + next_size)
                        del free_blocks[idx]
                return

        # Check merge with right neighbor (if not merged with left)
        # If we are here, we haven't merged with left.
        # The insertion point is idx.
        if idx < len(free_blocks):
            next_addr, next_size = free_blocks[idx]
            if addr + size == next_addr:
                # Merge with right
                free_blocks[idx] = (addr, size + next_size)
                return

        # No merge, insert at idx
        free_blocks.insert(idx, (addr, size))

    def find_best_fit(req_size):
        # Find index of smallest block >= req_size, tie-break lowest address
        best_idx = -1
        best_size = float('inf')

        for i, (addr, blk_size) in enumerate(free_blocks):
            if blk_size >= req_size:
                if blk_size < best_size:
                    best_size = blk_size
                    best_idx = i
                # If sizes are equal, the one with lower address comes first in sorted list,
                # so we keep the first one found (strict < check handles this)
        return best_idx

    for op in ops:
        if len(op) == 3:
            name, id_val, n_val = op
        elif len(op) == 2:
            name, id_val = op
            n_val = None
        else:
            raise ValueError("Invalid operation shape")

        if name not in ("alloc", "realloc", "free"):
            raise ValueError("Invalid operation name")

        if not isinstance(id_val, int) or isinstance(id_val, bool):
            raise ValueError("id must be an integer")
        if not (0 <= id_val <= 10**9):
            raise ValueError("id out of range")

        if name in ("alloc", "realloc"):
            if not isinstance(n_val, int) or isinstance(n_val, bool):
                raise ValueError("n must be an integer")
            if not (1 <= n_val <= 10**12):
                raise ValueError("n out of range")

            req_size = round_up(n_val)

            if name == "alloc":
                if id_val in allocated:
                    raise ValueError("id is already allocated")

                target_idx = find_best_fit(req_size)

                if target_idx == -1:
                    results.append(-1)
                else:
                    addr, blk_size = free_blocks[target_idx]
                    # Allocate
                    allocated[id_val] = (addr, req_size)
                    results.append(addr)

                    if blk_size > req_size:
                        # Split block
                        rem_addr = addr + req_size
                        rem_size = blk_size - req_size
                        del free_blocks[target_idx]
                        # Insert remainder. Since rem_addr > addr, and list is sorted,
                        # it should be inserted at target_idx (which is now the position
                        # of the next block, or end of list).
                        free_blocks.insert(target_idx, (rem_addr, rem_size))
                    else:
