def sim_best_fit_heap(size, ops):
    # Validation of size
    if not isinstance(size, int) or isinstance(size, bool):
        raise ValueError("size must be an integer")
    if size < 8 or size > 10**12 or size % 8 != 0:
        raise ValueError("size must be between 8 and 10^12 and a multiple of 8")

    if not isinstance(ops, list):
        raise ValueError("ops must be a list")

    allocated = {}  # id -> (addr, size)
    free_blocks = [(0, size)]  # list of (addr, size), sorted by addr

    results = []

    def round_up(n):
        return (n + 7) // 8 * 8

    def insert_free(addr, size):
        # Insert (addr, size) into free_blocks and coalesce with neighbors
        # free_blocks is sorted by address
        idx = bisect.bisect_left(free_blocks, (addr, 0))

        # Check merge with left neighbor
        if idx > 0:
            prev_addr, prev_size = free_blocks[idx-1]
            if prev_addr + prev_size == addr:
                # Merge with left
                free_blocks[idx-1] = (prev_addr, prev_size + size)
                # Now check if the merged block merges with the right neighbor (at idx)
                # Note: if idx == len(free_blocks), there is no right neighbor
                if idx < len(free_blocks):
                    curr_addr, curr_size = free_blocks[idx-1]
                    next_addr, next_size = free_blocks[idx]
                    if curr_addr + curr_size == next_addr:
                        # Merge with right
                        free_blocks[idx-1] = (curr_addr, curr_size + next_size)
                        del free_blocks[idx]
                return

        # Check merge with right neighbor (if not merged with left)
        # If we are here, we haven't merged with left.
        # The insertion point is idx.
        if idx < len(free_blocks):
            next_addr, next_size = free_blocks[idx]
            if addr + size == next_addr:
                # Merge with right
                free_blocks[idx] = (addr, size + next_size)
                return

        # No merge, insert at idx
        free_blocks.insert(idx, (addr, size))

    def find_best_fit(req_size):
        # Find index of smallest block >= req_size, tie-break lowest address
        best_idx = -1
        best_size = float('inf')

        for i, (addr, blk_size) in enumerate(free_blocks):
            if blk_size >= req_size:
                if blk_size < best_size:
                    best_size = blk_size
                    best_idx = i
                # If sizes are equal, the one with lower address comes first in sorted list,
                # so we keep the first one found (strict < check handles this)
        return best_idx

    for op in ops:
        if len(op) == 3:
            name, id_val, n_val = op
        elif len(op) == 2:
            name, id_val = op
            n_val = None
