    live_map = {} # id -> (addr, size)
    free_blocks = [(0, size)] # list of (addr, size) sorted by addr

    def round_up(x):
        return (x + 7) // 8 * 8

    def release_block(addr, size):
        # 1. Check right neighbor
        # Find block starting at addr + size
        right_idx = -1
        for i, (a, s) in enumerate(free_blocks):
            if a == addr + size:
                right_idx = i
                break
            if a > addr + size:
                break

        if right_idx != -1:
            _, r_size = free_blocks.pop(right_idx)
            size += r_size
            # addr unchanged

        # 2. Check left neighbor
        # Find block ending at addr
        left_idx = -1
        for i, (a, s) in enumerate(free_blocks):
            if a + s == addr:
                left_idx = i
                break
            if a > addr:
                break

        if left_idx != -1:
            l_addr, l_size = free_blocks.pop(left_idx)
            addr = l_addr
            size += l_size

        # 3. Insert
        ins_idx = len(free_blocks)
        for i, (a, s) in enumerate(free_blocks):
            if a > addr:
                ins_idx = i
                break
        free_blocks.insert(ins_idx, (addr, size))

