                if req == cur_size:
                    results.append(addr)
                elif req < cur_size:
                    # Shrink in place
                    live_map[id_val] = (addr, req)
                    release_block(addr + req, cur_size - req)
                    results.append(addr)
                else:
                    # req > cur_size
                    # Try grow in place
                    # Check right neighbor
                    right_idx = -1
                    right_size = 0
                    for i, (a, s) in enumerate(free_blocks):
                        if a == addr + cur_size:
                            right_idx = i
                            right_size = s
                            break
                        if a > addr + cur_size:
                            break

                    needed = req - cur_size
                    if right_idx != -1 and right_size >= needed:
                        # Grow in place
                        free_blocks.pop(right_idx)
                        if right_size > needed:
                            free_blocks.insert(right_idx, (addr + cur_size, right_size - needed))
                        live_map[id_val] = (addr, req)
                        results.append(addr)
                    else:
                        # Best fit search for new block
                        # Old block is still allocated, so not in free_blocks
                        best_idx = -1
                        best_size = float('inf')

                        for i, (a, s) in enumerate(free_blocks):
                            if s >= req:
                                if s < best_size:
                                    best_size = s

                        if best_size == float('inf'):
                            results.append(-1)
