            id_val, n = op[1], op[2]
            if not isinstance(id_val, int) or isinstance(id_val, bool):
                raise ValueError("id must be int")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("n must be int")
            if n < 1 or n > 10**12:
                raise ValueError("n out of range")
            if id_val < 0 or id_val > 10**9:
                raise ValueError("id out of range")

            if id_val not in live_map:
                results.append(-1)
            else:
                addr, cur_size = live_map[id_val]
                req = round_up(n)

                if req == cur_size:
                    results.append(addr)
                elif req < cur_size:
                    # Shrink in place
                    live_map[id_val] = (addr, req)
                    release_block(addr + req, cur_size - req)
                    results.append(addr)
                else:
                    # req > cur_size
                    # Try grow in place
                    # Check right neighbor
                    right_idx = -1
                    right_size = 0
                    for i, (a, s) in enumerate(free_blocks):
                        if a == addr + cur_size:
                            right_idx = i
                            right_size = s
                            break
                        if a > addr + cur_size:
                            break

                    needed = req - cur_size
                    if right_idx != -1 and right_size >= needed:
                        # Grow in place
                        free_blocks.pop(right_idx)
                        if right_size > needed:
                            # The remaining free block starts at the end of the new allocation
                            free_blocks.insert(right_idx, (addr + req, right_size - needed))
                        live_map[id_val] = (addr, req)
                        results.append(addr)
                    else:
                        # Best fit search for new block
                        # Old block is still allocated, so not in free_blocks
                        best_idx = -1
                        best_size = float('inf')

                        for i, (a, s) in enumerate(free_blocks):
                            if s >= req:
                                if s < best_size:
                                    best_size = s
                                    best_idx = i

                        if best_idx == -1:
                            results.append(-1)
                        else:
                            # Found
                            a, s = free_blocks.pop(best_idx)
                            # Move allocation
                            live_map[id_val] = (a, req)
                            # Release old block
                            release_block(addr, cur_size)
                            # Split new block if needed
                            if s > req:
                                release_block(a + req, s - req)
                            results.append(a)
            continue

    return results, free_blocks

def rank_mini_league(results):
    # Validation of input
    if not isinstance(results, list):
