        if not isinstance(away, str) or not away:
            raise ValueError("Away team must be a non-empty string")
        if home == away:
            raise ValueError("Home and away teams must be different")

        # Check goals are ints but not bools
        if type(h_goals) is not int or isinstance(h_goals, bool):
            raise ValueError("Home goals must be an integer (bool is not allowed)")
        if type(a_goals) is not int or isinstance(a_goals, bool):
            raise ValueError("Away goals must be an integer (bool is not allowed)")

        if not (0 <= h_goals <= 99) or not (0 <= a_goals <= 99):
            raise ValueError("Goals must be between 0 and 99")

        teams.add(home)
        teams.add(away)
        match_list.append((home, away, h_goals, a_goals))

    if not teams:
        return []

    # Calculate Overall Stats
    stats = {t: {'points': 0, 'gs': 0, 'gc': 0} for t in teams}

    for h, a, hg, ag in match_list:
        # Home team stats
        stats[h]['gs'] += hg
        stats[h]['gc'] += ag
        if hg > ag:
            stats[h]['points'] += 3
        elif hg == ag:
            stats[h]['points'] += 1

        # Away team stats
        stats[a]['gs'] += ag
        stats[a]['gc'] += hg
        if ag > hg:
            stats[a]['points'] += 3
        elif ag == hg:
            stats[a]['points'] += 1

    # Group teams by total points
    groups = {}
    for t, s in stats.items():
        p = s['points']
        if p not in groups:
            groups[p] = []
        groups[p].append(t)

    # Process groups from highest points to lowest
    sorted_points = sorted(groups.keys(), reverse=True)
    final_order = []

    for p in sorted_points:
        group = groups[p]
        if len(group) == 1:
            final_order.append(group[0])
            continue

        # Mini League Tie-break logic
        group_set = set(group)
        # Filter matches where both teams are in the current group
        mini_matches = [m for m in match_list if m[0] in group_set and m[1] in group_set]

        # Calculate mini stats for each team in the group
        mini_stats = {}
        for t in group:
            mp = 0
            mgs = 0
            mgc = 0
            mag = 0  # mini away goals

            for h, a, hg, ag in mini_matches:
                if t == h:
                    mgs += hg
                    mgc += ag
                    if hg > ag:
                        mp += 3
                    elif hg == ag:
                        mp += 1
                if t == a:
                    mgs += ag
                    mgc += hg
                    mag += ag
                    if ag > hg:
                        mp += 3
                    elif ag == hg:
                        mp += 1

            mgd = mgs - mgc
            mini_stats[t] = {'mp': mp, 'mgd': mgd, 'mgs': mgs, 'mag': mag}

        # Sort the group based on mini criteria, then overall criteria, then name
        def sort_key(t):
            ms = mini_stats[t]
            os = stats[t]
            ogd = os['gs'] - os['gc']
            ogs = os['gs']
            # Higher values are better, so negate for ascending sort
            # Name is ascending (plain str comparison)
            return (-ms['mp'], -ms['mgd'], -ms['mgs'], -ms['mag'], -ogd, -ogs, t)

        group.sort(key=sort_key)
        final_order.extend(group)

    return final_order

